// th15_s2_w02 — TH15 Stage 2 道中
// 源：st02.ecl.txt:951-966(MainSub01) / 331-354(GirlC01) / 356-414(GirlC01_at)

const TH15_RICE: int = 480;   // 源 etSprite(0, 8, 6)：type8=RICE，color6
const TIME_LIMIT: int = 1924; // 120 缓冲 + 1800 排程/退场估计 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 376 etEx type4 ACCEL：a=230、r=0.013、s=π/2(向下)；376 前的 SPEEDUP 为表现层，省略
xformdef DOWN_ACCEL {
    set_gravity(0fx, 0.013fx);
    wait(230);
    set_gravity(0fx, 0fx);
}

// 源 GirlC01_at 356-414：三轮，每轮自机角取样一次，环速从 1.0 起按档递增
sub girl_shoot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;        // 源 363-370 压栈 1/5/7/9（!LO 取 L）
    var step: fx = 0.3fx;  // 源 377 diffF(%B) 0.3/0.3/0.3/0.2
    var waves: int = 6;    // 源 383 diffI($D) 6/6/12/16
    var gap: int = 8;      // 源 389-396 压栈 8/8/6/5
    var rest: int = 60;    // 源 401-408 的 60/60/10/10
    if rank >= RANK_NORMAL { n = 5; }
    if rank >= RANK_HARD { n = 7; waves = 12; gap = 6; rest = 10; }
    if rank >= RANK_LUNATIC { n = 9; waves = 16; gap = 5; rest = 10; step = 0.2fx; }

    sh_reset(0);
    sh_sprite(0, TH15_RICE, 6);
    sh_aim(0, 0);
    sh_ring(0, 1);         // 源 etAim(0,3) 固定方向整周环
    sh_count(0, n, 1);
    sh_xform(0, DOWN_ACCEL);

    for outer in 0..3 {    // 源 378 $C = 3
        sh_angle(0, aim_player(), 0deg); // 源 382：每轮只取样一次自机角
        var speed: fx = 1fx;             // 源 381 diffF(%A) 恒 1.0
        for w in 0..waves {
            sh_speed(0, speed, 0fx);
            speed = speed + step;
            sh_fire(0);
            wait(gap);
        }
        wait(rest);
    }
}

// 源 GirlC01 331-354
async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);  // 源 setHurtbox(32,32)
    set_hitbox(12fx);   // 源 setHitbox(24,24)
    move_vel(0, aim_player(), 3fx, EASE_LINEAR);    // 源 342 moveVel(%ANGLE_PLAYER, 3.0)
    move_vel(80, 90deg, 0.01fx, EASE_QUAD_IN);      // 源 343 moveVelTime(80,1,π/2,0.01)
    girl_shoot();
    move_vel(0, -90deg, 0fx, EASE_LINEAR);          // 源 345 moveVel(-π/2, 0.0)
    move_vel(70, -90deg, 4fx, EASE_QUAD_IN);        // 源 346 moveVelTime(70,1,-π/2,4.0)
    wait(70);
    loop { wait(1000); } // 源 448 → 428 的 wait(1000) 循环
}

// 源 MainSub01 951-966：四组双 GirlC01，组间 120 帧
async sub pattern() {
    wait(OPENING_BUFFER); // 卡帧 120 = 源 MainSub01 帧 0
    _ = spawn_enemy(128fx, -24fx, 700, 0, 1000, 0, girl);
    _ = spawn_enemy(-128fx, -24fx, 700, 0, 1000, 0, girl);
    wait(120);
    _ = spawn_enemy(192fx, -24fx, 700, 0, 1000, 0, girl);
    _ = spawn_enemy(-64fx, -24fx, 700, 0, 1000, 0, girl);
    wait(120);
    _ = spawn_enemy(64fx, -24fx, 700, 0, 1000, 0, girl);
    _ = spawn_enemy(-192fx, -24fx, 700, 0, 1000, 0, girl);
    wait(120);
    _ = spawn_enemy(32fx, -24fx, 700, 0, 1000, 0, girl);
    _ = spawn_enemy(-32fx, -24fx, 700, 0, 1000, 0, girl);
    wait(60);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
